import {SKINS,DRIVERS,BURN_ITEMS,ownsItem,burnDemo} from './collection.mjs?v=37';
export function createCollectionUI(api){
 let tab='cars',selected='van',message='',pending=false,generation=0;
 const $=id=>document.getElementById(id),p=()=>api.profile(),w=()=>api.wallet.state();
 const items=()=>tab==='cars'?Object.values(api.cars).sort((a,b)=>(a.itemId||0)-(b.itemId||0)):tab==='skins'?SKINS:DRIVERS;
 const kind=item=>item.kind||'car';
 const owns=item=>item.itemId?ownsItem(p().collection,item,w().live?w().mask:null):kind(item)==='car'?p().unlocked.includes(item.id):true;
 const equipped=item=>kind(item)==='car'?p().selected===item.id:kind(item)==='skin'?p().collection.skin===item.id:p().collection.driver===item.id;
 const format=value=>{const decimals=api.wallet.config.decimals,s=value.toString().padStart(decimals+1,'0');if(!decimals)return s;const fraction=s.slice(-decimals).replace(/0+$/,'');return s.slice(0,-decimals)+(fraction?'.'+fraction:'');};
 const symbol=()=>w().live?api.wallet.config.symbol:'DEMO TOKENS';
 const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function equip(item){if(!owns(item))return;api.equip(item);const saved=api.save();message=item.name+(saved?' EQUIPPED · SAVED':' EQUIPPED · SESSION ONLY');render();}
 function render(){
  generation++;const list=items(),item=list.find(i=>i.id===selected)||list[0];selected=item.id;const owned=owns(item),isEquipped=owned&&equipped(item),state=w();
  const balance=state.live?(state.account?format(state.balance):'—'):p().collection.balance.toLocaleString();
  api.modal(`<button class="modal-close" data-close aria-label="Close collection">×</button><div class="collection-heading"><div><span class="collection-eyebrow">LAST EXIT / YOUR COLLECTION</span><h2 id="dialogTitle">MAKE IT YOURS.</h2></div><div class="collection-balance"><span>${escape(symbol())}</span><strong>${balance}</strong>${state.live?`<button class="small-btn" id="collectionWallet">${state.account?'REFRESH WALLET':'CONNECT WALLET'}</button>`:'<span class="preview-tag">BURN PREVIEW</span>'}</div></div>
  <div class="collection-notice">${state.live?'Burn tGETAWAY on Robinhood Chain Testnet. Test tokens have no monetary value.':`Try the full collection with demo tokens. These burns use no real crypto.`}</div>
  ${!state.live?'<div class="token-launch-note"><strong>TESTNET WORKSHOP OPEN</strong><br>Deploy or import your test shop to burn free tGETAWAY and verify ownership. <a href="/testnet/">Open testnet setup ↗</a> The future Pons launch is separate. <a href="/docs/#collection" target="_blank" rel="noopener noreferrer">How it works ↗</a></div>':''}
  <div class="collection-tabs" role="group" aria-label="Collection category">${[['cars','RIDES','06'],['skins','CAR SKINS','05'],['drivers','DRIVERS','03']].map(([id,label,n])=>`<button data-collection-tab="${id}" aria-pressed="${tab===id}">${label}<span>${n}</span></button>`).join('')}</div>
  <div class="collection-layout"><section class="collection-feature"><div class="collection-preview"><img src="${api.thumbnail(item)}" alt="${item.name} — in-game model"><span>${isEquipped?'EQUIPPED':owned?'OWNED':item.itemId?'BURN TO UNLOCK':'EARN IN GAME'}</span></div><div class="collection-feature-copy"><h3>${item.name}</h3><p>${item.description}</p><div class="collection-specs">${kind(item)==='car'?`<span><b>${Math.round(item.speed*4.6)}</b> KM/H</span><span><b>${item.seats}</b> SEATS</span><span><b>${item.health}</b> INTEGRITY</span>`:`<span>${kind(item)==='skin'?'WORKS ON EVERY RIDE':'YOUR PLAYABLE CHARACTER'}</span><span>COSMETIC</span>`}</div><button id="collectionEquip" class="primary" ${isEquipped||(!owned&&!item.itemId&&p().credits<item.price)?'disabled':''}>${isEquipped?'EQUIPPED':owned?'EQUIP':item.itemId?(state.live?'VIEW TOKEN BURN':'BURN '+item.cost.toLocaleString()+' DEMO TOKENS'):'UNLOCK · '+item.price.toLocaleString()+' CR'}</button>${!item.itemId&&kind(item)==='car'?`<p class="collection-small">${p().credits.toLocaleString()} banked credits available</p>`:''}</div></section>
  <section class="collection-grid" aria-label="Available ${tab}">${list.map(i=>`<button class="collection-item ${i.id===selected?'chosen':''}" data-collection-item="${i.id}" ${kind(i)==='car'?`data-car="${i.id}"`:''} aria-pressed="${i.id===selected}"><div><img src="${api.thumbnail(i)}" alt=""><span>${owns(i)?equipped(i)?'EQUIPPED':'OWNED':i.itemId?'BURN UNLOCK':'CREDITS'}</span></div><strong>${i.name}</strong><small>${owns(i)?'IN YOUR COLLECTION':i.itemId?state.live?'VIEW BURN PRICE':i.cost.toLocaleString()+' DEMO':i.price.toLocaleString()+' CR'}</small></button>`).join('')}</section></div>
  ${tab==='skins'&&item.id==='stock'?`<div class="paints"><span>FACTORY COLOR</span>${api.paints.map((c,i)=>`<button class="swatch ${p().paint===i?'active':''}" style="background:${c}" data-paint="${i}" aria-label="${['Sunburst','Turquoise','Vermilion','Electric blue'][i]} paint"></button>`).join('')}</div>`:''}
  ${!state.live?`<details class="collection-ledger"><summary>YOUR DEMO BURNS · ${p().collection.history.length} UNLOCKS</summary>${p().collection.history.length?[...p().collection.history].reverse().map(h=>`<div class="collection-ledger-row"><span>${BURN_ITEMS.find(i=>i.itemId===h.itemId)?.name||'ITEM'}<br><small>Saved on this device</small></span><b>−${h.cost.toLocaleString()} DEMO</b></div>`).join(''):'<p>Choose a skin to make your first demo burn.</p>'}</details>`:''}
  <p class="collection-status" id="collectionStatus" role="status">${escape(message||'Choose an item to inspect its actual in-game model.')}</p><div class="collection-footer"><p>${p().checkpoint?'A saved shift keeps its original car. Your next shift uses the ride you equip.':'Your equipped driver appears at home. Your equipped skin follows your ride.'}</p><button id="garageDrive" class="small-btn">${api.homeLabel?.()||'BACK TO APARTMENT'}</button></div>`,true);
  document.querySelectorAll('[data-collection-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.collectionTab;selected=tab==='cars'?p().selected:tab==='skins'?p().collection.skin:p().collection.driver;message='';render();});
  document.querySelectorAll('[data-collection-item]').forEach(b=>b.onclick=()=>{selected=b.dataset.collectionItem;message='';render();});
  document.querySelectorAll('[data-paint]').forEach(b=>b.onclick=()=>{p().paint=Number(b.dataset.paint);api.equip(SKINS[0]);api.save();render();});
  $('collectionEquip').onclick=()=>{if(owned)equip(item);else if(item.itemId)confirm(item);else{if(api.buy(item.id)){api.equip(item);api.save();message=item.name+' UNLOCKED';render();}}};
  $('garageDrive').onclick=api.home;
  if(state.live)$('collectionWallet').onclick=async()=>{const screen=generation,button=$('collectionWallet');button.disabled=true;try{await api.wallet.connect();api.reconcile();if(screen!==generation)return;message='WALLET COLLECTION UPDATED';}catch(e){if(screen!==generation)return;message=e.message;}render();};
 }
 async function confirm(item){
  if(pending)return;const state=w();if(state.live&&!state.account){message='Connect your wallet first to see the real burn amount.';render();return;}
  let price=BigInt(item.cost),screen=generation;
  try{if(state.live){$('collectionEquip').disabled=true;$('collectionStatus').textContent='Reading the on-chain price…';price=await api.wallet.quote(item.itemId);if(screen!==generation)return;}}catch(e){if(screen!==generation)return;message=e.message;render();return;}
  generation++;const amount=state.live?format(price):item.cost.toLocaleString(),balance=state.live?format(w().balance):p().collection.balance.toLocaleString(),enough=state.live?w().balance>=price:p().collection.balance>=item.cost;
  api.modal(`<button class="modal-close" id="burnBack" aria-label="Back to collection">×</button><span class="collection-eyebrow">${state.live?'TOKEN BURN':'DEMO BURN / NO REAL TOKENS'}</span><h2 id="dialogTitle">UNLOCK ${item.name}?</h2><div class="burn-review"><img src="${api.thumbnail(item)}" alt="${item.name}"><div><span>YOU BURN</span><strong>${amount}</strong><b>${escape(symbol())}</b><p>${state.live?'The tokens are destroyed. This item unlocks for your connected wallet after confirmation.':'Demo tokens leave your preview balance. The item becomes playable and saves on this device.'}</p></div></div><div class="instruction"><span>Your balance</span><b>${balance} ${escape(symbol())}</b></div><div class="instruction"><span>You receive</span><b>${item.name}</b></div><p class="collection-small">${state.live?'Your wallet will ask for an exact token approval, then a burn transaction. Network fees are additional.':'This is a preview price. Real token burns are not enabled yet.'}</p><p id="burnStatus" class="collection-status" role="status"></p><button id="burnConfirm" class="primary" ${enough?'':'disabled'}>${enough?(state.live?'CONFIRM TOKEN BURN':'CONFIRM DEMO BURN'):'NOT ENOUGH TOKENS'}</button><button id="burnCancel" class="small-btn burn-cancel">BACK TO COLLECTION</button>`,false);
  $('burnBack').onclick=$('burnCancel').onclick=()=>{if(!pending)render();};
  $('burnConfirm').onclick=async()=>{if(pending)return;pending=true;$('burnConfirm').disabled=true;$('burnCancel').disabled=true;$('burnBack').disabled=true;try{
   if(state.live)await api.wallet.unlock(item.itemId,price,text=>{$('burnStatus').textContent=text;});else burnDemo(p().collection,item.itemId);
   api.reconcile();api.equip(item);const saved=api.save();message=item.name+' UNLOCKED & EQUIPPED'+(!saved?' · SESSION ONLY':'');pending=false;render();
  }catch(e){$('burnStatus').textContent=e.message;$('burnConfirm').disabled=false;$('burnCancel').disabled=false;$('burnBack').disabled=false;pending=false;}};
 }
 return {open(options={}){if(pending)return;if(options.tab&&['cars','skins','drivers'].includes(options.tab))tab=options.tab;if(options.selected)selected=options.selected;render();if(options.confirm){const item=items().find(i=>i.id===selected);if(item?.itemId&&!owns(item))confirm(item);}},invalidate(){if(!pending)generation++;},isBusy:()=>pending};
}
